import { Buffer, isUtf8 } from 'node:buffer';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { mkdir, mkdtemp, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, extname, join, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { gzipSync } from 'node:zlib';

// Deliberately conservative project budgets, not Cloudflare plan limits.
const ASSET_BUDGET = 2 * 1024 * 1024;
const WORKER_BUDGET = 8 * 1024 * 1024;
const GZIP_BUDGET = 3 * 1024 * 1024;
const CONTENT_TYPES = Object.freeze({
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.json': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
});

export function stagingHtml(html) {
  const title = /<title>[^<]*<\/title>/;
  const description = /<meta name="description" content="[^"]*"\s*\/?\s*>/;
  if (!title.test(html) || !description.test(html)) throw new Error('Runtime HTML metadata is missing or needs review');
  return html.replace(title, '<title>ToothTalk · Synthetic Staging</title>')
    .replace(description, '<meta name="description" content="ระบบทดสอบนัดหมายทันตกรรม ใช้ข้อมูลสมมติเท่านั้น ไม่รับข้อมูลผู้ป่วยจริง" />');
}

export async function collectStaticAssets(directory, maxBytes = ASSET_BUDGET) {
  const assets = {};
  let bytes = 0;
  async function visit(path) {
    const entries = await readdir(path, { withFileTypes: true });
    for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name, 'en'))) {
      const filename = join(path, entry.name);
      const assetPath = `/${relative(directory, filename).split('\\').join('/')}`;
      if (entry.isSymbolicLink()) throw new Error(`Asset symbolic link is not allowed: ${assetPath}`);
      if (entry.name.startsWith('.') || assetPath === '/api' || assetPath.startsWith('/api/')) {
        throw new Error(`Private or API asset path is not allowed: ${assetPath}`);
      }
      if (entry.isDirectory()) { await visit(filename); continue; }
      const contentType = CONTENT_TYPES[extname(entry.name)];
      if (!entry.isFile() || !contentType) throw new Error(`Unsupported asset type: ${assetPath}`);
      const content = await readFile(filename);
      bytes += content.byteLength;
      if (bytes > maxBytes) throw new Error('Embedded assets exceed the project byte budget');
      if (!isUtf8(content)) throw new Error(`Asset must be valid UTF-8: ${assetPath}`);
      const body = content.toString('utf8');
      if (/sourceMappingURL\s*=/.test(body)) throw new Error(`Public source map reference is not allowed: ${assetPath}`);
      assets[assetPath] = { body, contentType };
    }
  }
  await visit(directory);
  if (!assets['/index.html']) throw new Error('Production assets must contain index.html');
  return assets;
}

export function renderAssetModule(assets) {
  const entries = Object.entries(assets).sort(([a], [b]) => a.localeCompare(b, 'en'));
  return '// Generated by scripts/build-runtime.mjs. Do not edit or commit.\n'
    + 'export const assets: Readonly<Record<string, Readonly<{ body: string; contentType: string }>>> = Object.freeze({\n'
    + entries.map(([path, asset]) => `  ${JSON.stringify(path)}: Object.freeze(${JSON.stringify(asset)})`).join(',\n')
    + '\n});\n';
}

export function assertProductionModuleIds(ids) {
  for (const id of ids) {
    const normalized = id.replaceAll('\\', '/');
    if (/(^|\/)src\/demo\//.test(normalized) || /(^|\/)tests\//.test(normalized)) {
      throw new Error(`Non-production module in runtime build: ${normalized}`);
    }
  }
}

export function measureBundle(bundle, maxBytes = WORKER_BUDGET, maxGzipBytes = GZIP_BUDGET) {
  const bytes = bundle.byteLength;
  const gzipBytes = gzipSync(bundle).byteLength;
  if (bytes > maxBytes || gzipBytes > maxGzipBytes) throw new Error('Worker exceeds the project bundle budget');
  return { bytes, gzipBytes, sha256: createHash('sha256').update(bundle).digest('hex') };
}

function verifiedOaUrl(config) {
  const value = config.vars?.LINE_VERIFIED_OA_URL;
  if (value === undefined) return undefined;
  // Operationally verified OA URLs only. Never publish credentials, query data,
  // custom ports, redirects to arbitrary hosts or a guessed default handle.
  if (typeof value !== 'string' || !/^https:\/\/(?:line\.me\/R\/ti\/p\/(?:@|%40)[A-Za-z0-9._-]+|lin\.ee\/[A-Za-z0-9]+)$/.test(value)) {
    throw new Error('Invalid verified OA URL');
  }
  return value;
}

export function publicBuildDefines(config) {
  const { LINE_LIFF_ID: liffId, LINE_CHANNEL_ID: channelId, APP_STAGE: stage } = config.vars ?? {};
  if (typeof liffId !== 'string' || !/^\d+-[A-Za-z0-9]+$/.test(liffId)
      || typeof channelId !== 'string' || !/^\d+$/.test(channelId)
      || !liffId.startsWith(`${channelId}-`) || stage !== 'synthetic-staging') {
    throw new Error('Missing or incompatible public staging configuration');
  }
  return {
    'import.meta.env.VITE_LIFF_ID': JSON.stringify(liffId),
    'import.meta.env.VITE_APP_STAGE': JSON.stringify(stage),
    ...(verifiedOaUrl(config) === undefined ? {} : { 'import.meta.env.VITE_VERIFIED_LINE_OA_URL': JSON.stringify(verifiedOaUrl(config)) }),
  };
}

export function uploadMetadata(config) {
  verifiedOaUrl(config);
  const publicNames = new Set(['APP_MODE', 'APP_STAGE', 'APP_ORIGIN', 'AUTH_MODE', 'MESSAGING_MODE', 'COMBINED_NOTIFICATIONS_ENABLED', 'NOTIFICATION_READINESS_ENABLED', 'LINE_CHANNEL_ID', 'LINE_LIFF_ID', 'LINE_PROVIDER_ID', 'LINE_MANUAL_APPROVAL_ENABLED', 'LINE_BOT_INFO_ENABLED', 'LINE_MESSAGING_BASIC_ID', 'LINE_VERIFIED_OA_URL']);
  if (Object.entries(config.vars ?? {}).some(([name, value]) => !publicNames.has(name) || typeof value !== 'string')) {
    throw new Error('Runtime config must contain only allowlisted public variables');
  }
  if (config.preview_urls !== false || config.logpush !== false || config.upload_source_maps !== false
      || config.observability?.enabled !== false || config.observability?.logs?.enabled !== false
      || config.observability?.logs?.invocation_logs !== false || config.observability?.traces?.enabled !== false) {
    throw new Error('Runtime previews, logs, traces and source maps must remain disabled');
  }
  if (config.assets) throw new Error('Separate asset uploads are not supported by this runtime package');
  const hyperdrive = config.hyperdrive ?? [];
  if (!Array.isArray(hyperdrive) || hyperdrive.length > 1 || hyperdrive.some(binding =>
    binding.binding !== 'DENTAL_DB' || typeof binding.id !== 'string'
    || !/^[a-f0-9]{32}$/.test(binding.id) || /^0+$/.test(binding.id) || 'localConnectionString' in binding)) {
    throw new Error('Hyperdrive requires a reviewed DENTAL_DB binding ID without credentials or placeholders');
  }
  return {
    main_module: 'entry.js',
    compatibility_date: config.compatibility_date,
    compatibility_flags: config.compatibility_flags,
    bindings: [
      ...Object.entries(config.vars).map(([name, text]) => ({ type: 'plain_text', name, text })),
      ...hyperdrive.map(({ binding: name, id }) => ({ type: 'hyperdrive', name, id })),
    ],
    logpush: false,
    observability: config.observability,
    keep_bindings: ['secret_text'],
  };
}

async function buildRuntime() {
  const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
  const generated = join(root, 'src/worker/generated-assets.ts');
  const output = join(root, 'artifacts/runtime');
  const temporary = await mkdtemp(join(tmpdir(), 'dental-runtime-build-'));
  await rm(output, { recursive: true, force: true });
  await rm(generated, { force: true });
  try {
    const config = JSON.parse(await readFile(join(root, 'wrangler.runtime.jsonc'), 'utf8'));
    const defines = publicBuildDefines(config);
    const metadata = uploadMetadata(config);
    process.env.APP_BUILD = 'production';
    process.env.NODE_ENV = 'production';
    const { build } = await import('vite');
    const browserModules = new Set();
    await build({
      root,
      mode: 'production',
      // Do not load local .env files or expose arbitrary VITE_ values to patients.
      envDir: false,
      envPrefix: [],
      define: defines,
      build: { outDir: join(root, 'dist'), emptyOutDir: true, sourcemap: false },
      plugins: [{
        name: 'runtime-production-graph',
        transformIndexHtml: stagingHtml,
        generateBundle() {
          for (const id of this.getModuleIds()) browserModules.add(id);
          assertProductionModuleIds(browserModules);
        },
      }],
    });
    const assets = await collectStaticAssets(join(root, 'dist'));
    await writeFile(generated, renderAssetModule(assets));
    const emptyEnvironment = join(temporary, 'empty.env');
    await writeFile(emptyEnvironment, '');
    const bundled = join(temporary, 'worker');
    const metafile = join(temporary, 'worker-meta.json');
    const result = spawnSync(process.execPath, [
      join(root, 'node_modules/wrangler/bin/wrangler.js'), 'deploy',
      '--config', join(root, 'wrangler.runtime.jsonc'), '--dry-run',
      '--outdir', bundled, '--metafile', metafile,
      '--env-file', emptyEnvironment, '--no-autoconfig',
    ], {
      cwd: root,
      env: {
        PATH: process.env.PATH,
        HOME: temporary,
        XDG_CONFIG_HOME: temporary,
        WRANGLER_SEND_METRICS: 'false',
        WRANGLER_LOG_PATH: join(temporary, 'logs'),
        CI: 'true',
      },
      encoding: 'utf8',
      maxBuffer: 2 * 1024 * 1024,
    });
    if (result.status !== 0) {
      throw new Error(`Wrangler local dry run failed (exit ${result.status ?? 'unavailable'}).\n${result.stdout ?? ''}${result.stderr ?? ''}`);
    }
    const workerModules = Object.keys(JSON.parse(await readFile(metafile, 'utf8')).inputs);
    assertProductionModuleIds(workerModules);
    const emitted = await readdir(bundled);
    if (emitted.some((filename) => filename !== 'entry.js' && filename !== 'entry.js.map' && filename !== 'README.md')) {
      throw new Error('Expected one bundled Worker module; review additional emitted modules before packaging');
    }
    // Wrangler generates a local debug map even when upload_source_maps=false.
    // Publish neither that map nor its trailing reference in the reviewed artifact.
    const script = (await readFile(join(bundled, 'entry.js'), 'utf8'))
      .replace(/^\/\/[#@] sourceMappingURL=.*(?:\r?\n|$)/gm, '');
    if (/sourceMappingURL\s*=/.test(script)) throw new Error('Unexpected source map reference in Worker bundle');
    const bundle = Buffer.from(script);
    const report = {
      buildMode: 'production',
      deployPerformed: false,
      worker: { file: 'entry.js', ...measureBundle(bundle) },
      assets: Object.fromEntries(Object.entries(assets).map(([path, asset]) => [path, {
        contentType: asset.contentType,
        bytes: Buffer.byteLength(asset.body),
        sha256: createHash('sha256').update(asset.body).digest('hex'),
      }])),
      browserModuleCount: browserModules.size,
      workerModuleCount: workerModules.length,
      productionGraphChecked: true,
      sourceMapsIncluded: false,
      projectBudgets: { assetBytes: ASSET_BUDGET, workerBytes: WORKER_BUDGET, workerGzipBytes: GZIP_BUDGET },
      missingBindings: metadata.bindings.some(binding => binding.type === 'hyperdrive' && binding.name === 'DENTAL_DB') ? [] : ['DENTAL_DB'],
      startupTimeMeasured: false,
    };
    await mkdir(output, { recursive: true });
    await writeFile(join(output, 'entry.js'), bundle);
    await writeFile(join(output, 'build-report.json'), `${JSON.stringify(report, null, 2)}\n`);
    await writeFile(join(output, 'upload-metadata.json'), `${JSON.stringify(metadata, null, 2)}\n`);
    console.log(`Local runtime package prepared: ${report.worker.bytes} bytes, ${report.worker.gzipBytes} gzip bytes, SHA-256 ${report.worker.sha256}. No deployment performed.`);
  } catch (error) {
    await rm(output, { recursive: true, force: true });
    await rm(generated, { force: true });
    throw error;
  } finally {
    await rm(temporary, { recursive: true, force: true });
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  if (process.argv.length !== 2) throw new Error('This local-only build does not accept deployment arguments');
  await buildRuntime();
}
